<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Untitled Document</title>
    <style>
        body {
            margin: 0;
            padding: 40px;
            font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
            line-height: 1.5;
            max-width: 900px;
            margin-left: auto;
            margin-right: auto;
        }
        .page {
            page-break-after: always;
            position: relative;
        }
        .text-line {
            margin-bottom: 12px;
            min-height: 1.2em;
        }
        .left-column {
            float: left;
            width: 48%;
            margin-right: 4%;
        }
        .right-column {
            float: right;
            width: 48%;
        }
        .centered {
            text-align: center;
            margin: 20px 0;
        }
        .placeholder {
            border: 1px dashed #666;
            background: #f8f8f8;
            padding: 10px;
            text-align: center;
            font-style: italic;
            color: #555;
            margin: 10px 0;
        }
        .header {
            font-weight: bold;
            font-size: 1.4em;
            margin-bottom: 15px;
            text-align: center;
        }
    </style>
</head>
<body>
    <!-- Page 1: Header / Title Zone -->
    <div class="page">
        <div style="text-align: center; margin-bottom: 30px;">
            <div class="header">[Title: Bold Centered Large Font]</div>
            <div class="centered">[Subtitle or Tagline]</div>
            <div style="margin-top: 20px; text-align: center;">
                <div style="display: inline-block; border: 1px solid #000; padding: 15px 30px; background: #fff;">
                    [Logo / Image Placeholder]
                </div>
            </div>
        </div>

