                <div class="text-line">Line 2 of column 1</div>
                <div class="text-line">Line 3 of column 1</div>
                <div class="text-line">Line 4 of column 1</div>
            </div>
            <!-- Right Column -->
            <div style="flex: 1;">
                <div class="text-line">Line 1 of column 2</div>
                <div class="text-line">Line 2 of column 2</div>
                <div class="text-line">Line 3 of column 2</div>
                <div class="text-line">Line 4 of column 2</div>
            </div>
        </div>

